        xs[i],ys[i]=pts[2*i],pts[2*i+1]
    # Precompute the balls retained by an operation centered at each ball.
    keep=[]
    for k in range(n):
        mask=0
        for i in range(n):
            if i==k or not ((xs[i]<xs[k] and ys[i]<ys[k]) or (xs[i]>xs[k] and ys[i]>ys[k])):
                mask |= 1<<i
        keep.append(mask)
    start=(1<<n)-1
    seen={start}
    stack=[start]
    while stack:
        state=stack.pop()
        for k in range(n):
            if state>>k&1:
                nxt=state&keep[k]
                if nxt not in seen:
                    seen.add(nxt); stack.append(nxt)
    print(len(seen)%998244353)

