import sys
from collections import defaultdict

def factorize(x):
    out = []
    d = 2
    while d * d <= x:
        e = 0
        while x % d == 0:
            x //= d
            e += 1
        if e:
            out.append((d, e))
        d += 1 if d == 2 else 2
    if x > 1:
        out.append((x, 1))
    return out

def constrained_sum(p, steps, lower, total_variation):
    # Sum p^(sum of all heights) over walks staying at/above lower.
    # The starting height is also included in the weight.
    high = total_variation
    powers = [pow(p, h, MOD) for h in range(high + 1)]
    dp = [0] * (high + 1)
    for h in range(lower, high + 1):
        dp[h] = powers[h]

    for e in steps:
        nxt = [0] * (high + 1)
        if e == 0:
            for h in range(lower, high + 1):
                if dp[h]:
                    nxt[h] = dp[h] * powers[h] % MOD
        else:
            for h in range(lower, high + 1):
                value = dp[h]
                if not value:
                    continue
                down = h - e
                if down >= lower:
                    nxt[down] = (nxt[down] + value * powers[down]) % MOD
                up = h + e
                if up <= high:
                    nxt[up] = (nxt[up] + value * powers[up]) % MOD
        dp = nxt
    return sum(dp) % MOD

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    occurrences = defaultdict(dict)
    for i, value in enumerate(a):
        for p, e in factorize(value):
            occurrences[p][i] = e

    answer = 1
    for p, by_edge in occurrences.items():
        steps = [by_edge.get(i, 0) for i in range(n - 1)]
        total = sum(steps)
        all_nonnegative = constrained_sum(p, steps, 0, total)
        strictly_positive = constrained_sum(p, steps, 1, total)
        answer = answer * (all_nonnegative - strictly_positive) % MOD

    print(answer)

if __name__ == '__main__':
    main()

