def conv(a, b, m):
    out = [0] * m
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                if y:
                    k = i + j
                    if k >= m:
                        k -= m
                    out[k] = (out[k] + x * y) % MOD
    return out

def power(base, e, m):
    res = [0] * m
    res[0] = 1
    while e:
        if e & 1:
            res = conv(res, base, m)
        e >>= 1
        if e:
            base = conv(base, base, m)
    return res

