        freq[x] += 1
    # Walsh transform of the input frequency gives the signed parity sum
    length = 1
    while length < size:
        step = length << 1
        for start in range(0, size, step):
            for i in range(start, start + length):
                x, y = freq[i], freq[i + length]
                freq[i] = x + y
                freq[i + length] = x - y
        length = step
    # Fourier coefficients of x^K on the XOR group.
    vals = [pow(x, k, MOD) for x in range(size)]
    length = 1
