from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            buckets[b].append((a, i))

        count = [0] * (n + 1)
        sole_id = [-1] * (n + 1)
        max_heap = []
        gains = [0] * len(conflictingPairs)
        baseline = 0

        for right in range(1, n + 1):
            for left, pair_id in buckets[right]:
                if count[left] == 0:
                    heapq.heappush(max_heap, -left)
                    sole_id[left] = pair_id
                else:
                    sole_id[left] = -1
                count[left] += 1

            largest = -max_heap[0] if max_heap else 0
            baseline += right - largest

            if largest and count[largest] == 1:
                second = max(
                    -max_heap[1] if len(max_heap) > 1 else 0,
                    -max_heap[2] if len(max_heap) > 2 else 0,
                )
                gains[sole_id[largest]] += largest - second

        return baseline + max(gains)

