    N,M,Q=map(int,input().split())
    edges=[None]*M
    for i in range(M):
        a,b,c=map(int,input().split()); a-=1;b-=1
        edges[i]=(a,b,c)
    queries=[]
    closed=[False]*M
    for _ in range(Q):
        t,*v=map(int,input().split())
        if t==1:
            i=v[0]-1; closed[i]=True
            queries.append((1,i))
        else:
            x,y=v[0]-1,v[1]-1
            queries.append((2,x,y))
    INF=10**30
    d=[[INF]*N for _ in range(N)]
    for i in range(N): d[i][i]=0
    for i,(a,b,c) in enumerate(edges):
        if not closed[i]:
            d[a][b]=d[b][a]=c
    for k in range(N):
        dk=d[k]
        for i in range(N):
            dik=d[i][k]
            if dik==INF: continue
            di=d[i]
            for j in range(N):
                z=dik+dk[j]
                if z<di[j]: di[j]=z
    ans=[]
    for q in reversed(queries):
        if q[0]==2:
            val=d[q[1]][q[2]]
            ans.append(str(val if val<INF else -1))
        else:
            a,b,c=edges[q[1]]
            da=[d[i][a] for i in range(N)]
            db=[d[i][b] for i in range(N)]
            for i in range(N):
                di=d[i]; x=da[i]+c; y=db[i]+c
