class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Binomial coefficients for choosing the suffix bits.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # steps[x] = number of popcount operations needed to reach 1.
        steps = [0] * (n + 1)
        for x in range(2, n + 1):
            steps[x] = 1 + steps[x.bit_count()]

        ans = 0
        for weight in range(1, n + 1):
            # A number with this weight needs one step to become weight,
            # followed by steps[weight] steps to reach 1.
            if steps[weight] + 1 > k:
                continue

            count = 0
            ones_so_far = 0
            for i, bit in enumerate(s):
                if bit == '1':
                    remaining = n - i - 1
                    need = weight - ones_so_far
                    if 0 <= need <= remaining:
                        count += comb[remaining][need]
                    ones_so_far += 1
            ans = (ans + count) % MOD

        return ans

