import sys
from collections import deque

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:
        return
    it=iter(data)
    n=next(it); m=next(it); q=next(it)
    people=[]
    for _ in range(m):
        s=next(it)-1; t=next(it)-1
        people.append((s,t))
    queries=[(next(it)-1,next(it)-1) for _ in range(q)]
    out=[]
    for l,r in queries:
        # Edge u -> v, weight w represents value[v] >= value[u] + w.
        adj=[[] for _ in range(n)]
        for i in range(l,r+1):
            s,t=people[i]
            adj[s].append((t,0)); adj[t].append((s,0))
            if s<t:
                for x in range(s+1,t):
                    adj[s].append((x,1))
            else:
                for x in range(t+1,s):
                    adj[x].append((s,1))
        dist=[0]*n
        cnt=[0]*n
        inq=[True]*n
        dq=deque(range(n))
        ok=True
        while dq and ok:
            u=dq.popleft(); inq[u]=False
            for v,w in adj[u]:
                nd=dist[u]+w
                if nd>dist[v]:
                    dist[v]=nd
                    cnt[v]=cnt[u]+1
                    if cnt[v]>=n:
                        ok=False
                        break
                    if not inq[v]:
                        # Small-label-first heuristic
                        if dq and dist[v]>dist[dq[0]]:
                            dq.appendleft(v)
                        else:
                            dq.append(v)
                        inq[v]=True
        out.append('Yes' if ok else 'No')
    sys.stdout.write('\n'.join(out))

if __name__=='__main__':
    main()

