import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    n = int(input())
    a = [input().strip() for _ in range(n)]
    incoming = [{} for _ in range(n)]
    outgoing = [{} for _ in range(n)]
    for u in range(n):
        for v, c in enumerate(a[u]):
            if c != '-':
                outgoing[u][c] = outgoing[u].get(c, 0) | (1 << v)
                incoming[v].setdefault(c, []).append(u)
    dist = [[-1] * n for _ in range(n)]
    seen = [0] * n
    q = deque()
    for i in range(n):
        dist[i][i] = 0
        seen[i] |= 1 << i
        q.append((i, i))
    for i in range(n):
        for j, c in enumerate(a[i]):
            if c != '-' and dist[i][j] == -1:
                dist[i][j] = 1
                seen[i] |= 1 << j
                q.append((i, j))
    while q:
        u, v = q.popleft()
        nd = dist[u][v] + 2
        for c, preds in incoming[u].items():
            base = outgoing[v].get(c, 0)
            if base:
                for p in preds:
                    bits = base & ~seen[p]
                    while bits:
                        bit = bits & -bits
                        bits -= bit
                        w = bit.bit_length() - 1
                        seen[p] |= bit
                        dist[p][w] = nd
                        q.append((p, w))
    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

if __name__ == '__main__':
    solve()

