from typing import List
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n,m=len(grid),len(grid[0])
        dirs=[(1,1),(1,-1),(-1,-1),(-1,1)]
        straight=[[[0]*m for _ in range(n)] for _ in range(4)]
        bent=[[[0]*m for _ in range(n)] for _ in range(4)]
        def nxt(v): return 0 if v==2 else 2
        for d,(dr,dc) in enumerate(dirs):
            rs=range(n-1,-1,-1) if dr==1 else range(n)
            cs=range(m-1,-1,-1) if dc==1 else range(m)
            nd=(d+1)%4
            for r in rs:
                for c in cs:
                    v=grid[r][c]
                    best=1
                    nr,nc=r+dr,c+dc
                    if 0<=nr<n and 0<=nc<m and grid[nr][nc]==nxt(v):
                        best+=straight[d][nr][nc]
                    straight[d][r][c]=best
                    best=1
                    if 0<=nr<n and 0<=nc<m and grid[nr][nc]==nxt(v):
                        best=max(best,1+bent[d][nr][nc])
                    nr,nc=r+dirs[nd][0],c+dirs[nd][1]
                    if 0<=nr<n and 0<=nc<m and grid[nr][nc]==nxt(v):
                        best=max(best,1+straight[nd][nr][nc])
                    bent[d][r][c]=best
        return max((bent[d][r][c] for r in range(n) for c in range(m) if grid[r][c]==1 for d in range(4)),default=0)

