from typing import List
from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        vals = list(range(1, n + 1))
        facts = [factorial(i) for i in range(n + 1)]

        def ways_after(rem, next_parity):
            m = len(rem)
            need = [0, 0]
            need[next_parity] = (m + 1) // 2
            need[1 - next_parity] = m // 2
            have = [0, 0]
            for x in rem:
                have[x % 2] += 1
            if have != need:
                return 0
            return facts[have[0]] * facts[have[1]]

        total = 0
        for x in vals:
            rem = [y for y in vals if y != x]
            total += ways_after(rem, 1 - (x % 2))
        if k > total:
            return []

        ans = []
        prev = None
        while vals:
            for x in vals:
                if prev is not None and x % 2 == prev % 2:
                    continue
                rem = [y for y in vals if y != x]
                cnt = ways_after(rem, 1 - (x % 2)) if rem else 1
                if k > cnt:
                    k -= cnt
                else:
                    ans.append(x)
                    vals = rem
                    prev = x
                    break
        return ans

