class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        N=m*n
        dist=(n*n*(m**3-m)+m*m*(n**3-n))//6
        fact=[1]*(N+1)
        for i in range(1,N+1): fact[i]=fact[i-1]*i%MOD
        def inv(x): return pow(x,MOD-2,MOD)
        ways=fact[N-2]*inv(fact[k-2])%MOD*inv(fact[N-k])%MOD
        return dist%MOD*ways%MOD

