class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        p10 = [1] * n
        for i in range(1, n):
            p10[i] = p10[i - 1] * 10 % k

        coeff = [0] * m
        for i in range(m):
            j = n - 1 - i
            coeff[i] = (p10[i] + (p10[j] if j != i else 0)) % k

        # suff[i][r]: the positions from i onward can contribute residue r.
        suff = [[False] * k for _ in range(m + 1)]
        suff[m][0] = True
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            row = suff[i]
            nxt = suff[i + 1]
            for r in range(k):
                for d in range(10):
                    if nxt[(r - c * d) % k]:
                        row[r] = True
                        break

        prefix = []
        residue = 0
        for i, c in enumerate(coeff):
            for d in range(9, -1, -1):
                if i == 0 and d == 0:
                    continue
                needed = (-residue - c * d) % k
                if suff[i + 1][needed]:
                    prefix.append(str(d))
                    residue = (residue + c * d) % k
                    break

        left = ''.join(prefix)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

