import sys
from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, M, L = data[:3]
    cards = data[3:]
    n = N + M + L

    a0 = (1 << N) - 1
    b0 = ((1 << M) - 1) << N
    full = (1 << n) - 1

    lower = []
    for x in cards:
        mask = 0
        for j, y in enumerate(cards):
            if y < x:
                mask |= 1 << j
        lower.append(mask)

    @lru_cache(None)
    def winning(a, b, turn):
        hand = a if turn == 0 else b
        if hand == 0:
            return False

        table = full ^ (a | b)
        while hand:
            bit = hand & -hand
            hand ^= bit
            i = bit.bit_length() - 1

            next_a = a ^ bit if turn == 0 else a
            next_b = b ^ bit if turn == 1 else b
            next_table = table | bit
            next_turn = 1 - turn

            # Play the card and do not take a card from the table.
            if not winning(next_a, next_b, next_turn):
                return True

            # Or take any table card with a strictly smaller number.
            choices = next_table & lower[i]
            while choices:
                take = choices & -choices
                choices ^= take
                if turn == 0:
                    if not winning(next_a | take, next_b, next_turn):
                        return True
                else:
                    if not winning(next_a, next_b | take, next_turn):
                        return True

        return False

    print("Takahashi" if winning(a0, b0, 0) else "Aoki")

if __name__ == "__main__":
    main()

