from bisect import bisect_left, bisect_right

class Solution:
    def _occurrences(self, text, pat):
        n, m = len(text), len(pat)
        if m == 0:
            return list(range(n + 1))

        pi = [0] * m
        j = 0
        for i in range(1, m):
            while j and pat[i] != pat[j]:
                j = pi[j - 1]
            if pat[i] == pat[j]:
                j += 1
            pi[i] = j

        out = []
        j = 0
        for i, ch in enumerate(text):
            while j and ch != pat[j]:
                j = pi[j - 1]
            if ch == pat[j]:
                j += 1
            if j == m:
                out.append(i - m + 1)
                j = pi[j - 1]
        return out

    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        ao = self._occurrences(s, a)
        bo = self._occurrences(s, b)
        co = self._occurrences(s, c)
        aends = [x + len(a) for x in ao]

        ans = len(s) + 1
        for x in bo:
            ai = bisect_right(aends, x) - 1
            if ai < 0:
                continue
            y = x + len(b)
            ci = bisect_left(co, y)
            if ci == len(co):
                continue
            ans = min(ans, co[ci] + len(c) - ao[ai])

        return -1 if ans == len(s) + 1 else ans

